def count_coprime_pairs(x0: int, y0: int) -> int:
    """
    Counts the number of ordered pairs of positive integers (P, Q) such that
    gcd(P, Q) == x0 and lcm(P, Q) == y0.

    Parameters:
    x0 (int): The required greatest common divisor of the pair.
    y0 (int): The required least common multiple of the pair.

    Returns:
    int: The number of ordered pairs (P, Q) satisfying the conditions.
    """
    # Validate inputs: both must be positive integers
    if x0 <= 0 or y0 <= 0:
        return 0

    # If y0 is not a multiple of x0, no such pair exists
    if y0 % x0 != 0:
        return 0

    # Helper function to compute gcd using Euclidean algorithm
    def _gcd(a: int, b: int) -> int:
        while b:
            a, b = b, a % b
        return a

    m = y0 // x0  # product of the co-prime factors a and b
    count = 0
    limit = int(m ** 0.5)
    for a in range(1, limit + 1):
        if m % a == 0:
            b = m // a
            if _gcd(a, b) == 1:
                if a == b:
                    count += 1
                else:
                    count += 2
    return count

def is_prime(num: int) -> bool:
    """
    Determine whether a given integer is a prime number.

    Parameters:
    num (int): The integer to check for primality.

    Returns:
    bool: True if num is a prime number, False otherwise.
    """
    if num <= 1:
        return False
    if num <= 3:
        return True
    if num % 2 == 0 or num % 3 == 0:
        return False
    i = 5
    while i * i <= num:
        if num % i == 0 or num % (i + 2) == 0:
            return False
        i += 6
    return True

def generate_numbers(n, rules) -> int:
    """
    Generate all unique numbers from the given number by applying transformation rules.
    Each rule allows a single digit to be transformed into another. A breadth-first search
    (BFS) is used to explore all possible transformations. The function returns the count
    of unique numbers that can be generated from the original number, including the number itself.

    Args:
    - n (int): The original integer number to transform.
    - rules (list of tuples): A list of transformation rules, where each rule is represented
                              as a tuple (x, y) indicating that digit x can be transformed into y.

    Returns:
    - int: The total count of unique numbers that can be generated.
    """
    # Input validation
    if not isinstance(n, int):
        raise TypeError("n must be an integer")
    if not isinstance(rules, list):
        raise TypeError("rules must be a list of tuples")
    for rule in rules:
        if not (isinstance(rule, tuple) and len(rule) == 2):
            raise ValueError("Each rule must be a tuple of two integers")
        if not (isinstance(rule[0], int) and isinstance(rule[1], int)):
            raise ValueError("Rule elements must be integers")
        if not (0 <= rule[0] <= 9 and 0 <= rule[1] <= 9):
            raise ValueError("Digits must be in the range 0-9")

    # Build mapping from digit to list of possible replacements
    mapping = {}
    for src, dst in rules:
        mapping.setdefault(src, []).append(dst)

    from collections import deque

    visited = set()
    queue = deque()

    # Start with the original number
    visited.add(n)
    queue.append(n)

    while queue:
        current = queue.popleft()
        current_str = str(current)
        for idx, ch in enumerate(current_str):
            digit = int(ch)
            if digit in mapping:
                for replacement in mapping[digit]:
                    # Replace the digit at position idx
                    new_str = current_str[:idx] + str(replacement) + current_str[idx+1:]
                    new_num = int(new_str)  # Convert to int to canonicalize (remove leading zeros)
                    if new_num not in visited:
                        visited.add(new_num)
                        queue.append(new_num)

    return len(visited)

def check_scenario(scenario: str, liar_count: set, statements: dict, days_of_week: set) -> bool:
    """
    Evaluates the consistency of a scenario where one participant is the criminal based on the given statements.

    Parameters:
    - scenario (str): The name of the participant being tested as the potential criminal.
    - liar_count (set): A set of names of participants who are assumed to be liars.
    - statements (dict): A dictionary mapping participant names to lists of their respective statements.
    - days_of_week (set): A set of strings representing the days of the week.

    Returns:
    - bool: True if the scenario is consistent with the statements, False otherwise.
    """
    # Helper to evaluate a single statement
    def evaluate_statement(speaker: str, stmt: str) -> bool:
        # Ignore statements that mention a day of the week
        stmt_lower = stmt.lower()
        for day in days_of_week:
            if day.lower() in stmt_lower:
                return None  # signal to ignore

        # Clean statement for easier matching
        cleaned = stmt.strip().rstrip('.').lower()

        # Speaker refers to themselves
        if cleaned == "i am guilty":
            return scenario.lower() == speaker.lower()
        if cleaned == "i am not guilty":
            return scenario.lower() != speaker.lower()

        # Statements about others
        if cleaned.endswith(" is guilty"):
            name = cleaned[:-len(" is guilty")].strip()
            return scenario.lower() == name
        if cleaned.endswith(" is not guilty"):
            name = cleaned[:-len(" is not guilty")].strip()
            return scenario.lower() != name

        # If statement doesn't match known patterns, treat it as neutral (doesn't affect consistency)
        return True

    # Iterate over all participants and their statements
    for participant, stmts in statements.items():
        for stmt in stmts:
            truth = evaluate_statement(participant, stmt)
            if truth is None:
                # Statement about a day of the week; ignore
                continue
            if participant in liar_count:
                if truth:
                    # Liars should not make true statements
                    return False
            else:
                if not truth:
                    # Non-liars should not make false statements
                    return False
    return True

